-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     'Store'                     AS \"Location Type\",     s.STORE                     AS \"Location ID\",     s.STORE_NAME                AS \"Location Name\",     s.STORE_NAME10              AS \"Location Name Short\",     CASE         WHEN s.STORE_CLOSE_DATE IS NOT NULL          AND s.STORE_CLOSE_DATE &lt;= SYSDATE THEN 'Closed'         WHEN s.STORE_OPEN_DATE &gt; SYSDATE   THEN 'Pre-Open'         ELSE 'Active'     END                         AS STATUS,     s.STORE_CLASS AS \"Store Class\",     s.STORE_TYPE AS \"Store Type\",     TO_CHAR(s.STORE_FORMAT)     AS \"Store Format\",     TO_CHAR(s.DISTRICT)         AS DISTRICT,     TO_CHAR(s.CHANNEL_ID)        AS \"Channel ID\",     s.CURRENCY_CODE  AS \"Currency Code\",     s.TIMEZONE_NAME AS \"Timezone Name\",     s.STOCKHOLDING_IND  AS \"Stockholding Indicator\",     s.STORE_MGR_NAME           AS \"Manager Name\",     s.PHONE_NUMBER AS \"Phone Number\",     s.FAX_NUMBER AS \"Fax Number\",     s.EMAIL,     s.STORE_OPEN_DATE           AS \"Open Date\",     s.STORE_CLOSE_DATE          AS \"Close Date\",     s.ACQUIRED_DATE AS \"Acquired Date\",     s.REMODEL_DATE AS \"Remodel Date\",     s.TOTAL_SQUARE_FT AS \"Total Square Feet\",     s.SELLING_SQUARE_FT AS \"Selling Square Feet\",     s.LINEAR_DISTANCE  AS \"Linear Distance\",     TO_CHAR(s.DEFAULT_WH)       AS \"Default Warehouse\",     s.ONLINE_STORE_IND           AS \"Online Indicator\",     s.CUSTOMER_ORDER_LOC_IND  AS \"Customer Order Location Ind\",     TO_CHAR(s.VAT_REGION)      AS \"VAT Region\",     s.VAT_INCLUDE_IND AS \"VAT Include Indicator\",     s.LEGAL_ENTITY  AS \"Legal Entity\",     s.TAX_ID  AS \"Tax ID\",     a.ADD_1  AS \"Address 1\", a.ADD_2, a.ADD_3,     a.CITY, a.STATE,     a.POST                      AS \"Zip Code\",     a.COUNTRY_ID, a.COUNTY,     a.LATITUDE, a.LONGITUDE FROM rds_wv_store s LEFT JOIN rds_wv_addr a     ON  a.MODULE            = 'ST'     AND a.KEY_VALUE_1       = TO_CHAR(s.STORE)     AND a.PRIMARY_ADDR_IND  = 'Y'     AND a.ADDR_TYPE         = '01' UNION ALL

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT     CASE         WHEN w.PHYSICAL_WH = w.WH THEN 'Physical Warehouse'         ELSE 'Virtual Warehouse'     END                         AS LOCATION_TYPE,     w.WH                        AS LOCATION_ID,     w.WH_NAME                   AS LOCATION_NAME,     NULL                        AS LOCATION_NAME_SHORT,     'Active'                    AS STATUS,     NULL                        AS STORE_CLASS,     w.VWH_TYPE                  AS STORE_TYPE,     NULL                        AS STORE_FORMAT,     NULL                        AS DISTRICT,     TO_CHAR(w.CHANNEL_ID)       AS CHANNEL_ID,     w.CURRENCY_CODE,     NULL                        AS TIMEZONE_NAME,     w.STOCKHOLDING_IND,     NULL                        AS MANAGER_NAME,     NULL                        AS PHONE_NUMBER,     NULL                        AS FAX_NUMBER,     w.EMAIL,     NULL                        AS OPEN_DATE,     NULL                        AS CLOSE_DATE,     NULL                        AS ACQUIRED_DATE,     NULL                        AS REMODEL_DATE,     NULL                        AS TOTAL_SQUARE_FT,     NULL                        AS SELLING_SQUARE_FT,     NULL                        AS LINEAR_DISTANCE,     TO_CHAR(w.DEFAULT_WH)       AS DEFAULT_WH,     NULL                        AS ONLINE_IND,     w.CUSTOMER_ORDER_LOC_IND,     TO_CHAR(w.VAT_REGION)       AS VAT_REGION,     NULL                        AS VAT_INCLUDE_IND,     w.LEGAL_ENTITY,     w.TAX_ID,     a.ADD_1, a.ADD_2, a.ADD_3,     a.CITY, a.STATE,     a.POST                      AS ZIP_CODE,     a.COUNTRY_ID, a.COUNTY,     a.LATITUDE, a.LONGITUDE FROM rds_wv_wh w LEFT JOIN rds_wv_addr a     ON  a.MODULE            = 'WH'     AND a.KEY_VALUE_1       = TO_CHAR(w.WH)     AND a.PRIMARY_ADDR_IND  = 'Y'     AND a.ADDR_TYPE         = '01'</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Location Type</ds:name><ds:datatype>varchar(18)</ds:datatype></ds:column><ds:column><ds:n